RRB.load({"id": "ntpc-full-5", "exam": "ntpc", "label": "NTPC UG full mock 5 (100 Q)", "questions": [{"s": "General Awareness", "t": "History", "q": "The Treaty of Salbai (1782) ended the First Anglo-Maratha War between the British and:", "o": ["The ruler of Mysore", "The Marathas", "The Sikhs", "The Nizam of Hyderabad"], "a": 1, "e": "The Treaty of Salbai (1782) ended the First Anglo-Maratha War (1775–82).", "qh": "सालबाई की संधि (1782) से अंग्रेज़ों और किसके बीच पहला युद्ध ख़त्म हुआ?", "oh": ["मैसूर के शासक", "मराठों", "सिखों", "हैदराबाद के निज़ाम"], "eh": "सालबाई की संधि (1782) से पहला आंग्ल-मराठा युद्ध (1775–82) ख़त्म हुआ।", "level": "tough"}, {"s": "General Awareness", "t": "Current Affairs", "q": "The 2026 G7 Summit (15–17 June) was hosted by France at which town?", "o": ["Évian-les-Bains", "Nice", "Biarritz", "Strasbourg"], "a": 0, "e": "France hosted the G7 summit at Évian-les-Bains from 15 to 17 June 2026. (Biarritz hosted it in 2019.)", "qh": "2026 का G7 शिखर सम्मेलन (15–17 जून) फ़्रांस ने किस शहर में आयोजित किया?", "oh": ["एवियाँ-ले-बैं", "नीस", "बियारिट्ज़", "स्ट्रासबर्ग"], "eh": "फ़्रांस ने 15 से 17 जून 2026 तक एवियाँ-ले-बैं में G7 सम्मेलन आयोजित किया। (2019 में यह बियारिट्ज़ में हुआ था।)", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "The main aim of the Pradhan Mantri Jan Dhan Yojana (2014) is:", "o": ["To give free LPG connections", "To provide crop insurance", "To open bank accounts for every household", "To build rural houses"], "a": 2, "e": "PMJDY (launched 28 August 2014) is a financial-inclusion scheme to give every household a basic bank account.", "qh": "प्रधानमंत्री जन धन योजना (2014) का मुख्य उद्देश्य क्या है?", "oh": ["मुफ़्त LPG कनेक्शन देना", "फ़सल बीमा देना", "हर परिवार का बैंक खाता खुलवाना", "गाँवों में मकान बनाना"], "eh": "PMJDY (28 अगस्त 2014 से) वित्तीय समावेशन की योजना है, ताकि हर परिवार का बैंक खाता हो।", "level": "easy"}, {"s": "General Awareness", "t": "Economy", "q": "According to the provisional estimates released by the NSO in June 2026, India's real GDP growth for 2025-26 was:", "o": ["6.5%", "8.2%", "7.7%", "7.1%"], "a": 2, "e": "The NSO (MoSPI) put real GDP growth for FY 2025-26 at 7.7%, up from 7.1% in 2024-25.", "qh": "जून 2026 में NSO द्वारा जारी अनंतिम अनुमानों के अनुसार 2025-26 में भारत की वास्तविक GDP वृद्धि दर कितनी रही?", "oh": ["6.5%", "8.2%", "7.7%", "7.1%"], "eh": "NSO (MoSPI) के अनुसार 2025-26 में वास्तविक GDP वृद्धि 7.7% रही, जो 2024-25 में 7.1% थी।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "Under the Kerala (Alteration of Name) Act, 2026, the State of Kerala was officially renamed as:", "o": ["Keralan", "Keralam", "Malanadu", "Kairali"], "a": 1, "e": "Parliament passed the Bill on 11–12 August 2026; the President assented on 14 August and the name 'Keralam' took effect from 25 August 2026.", "qh": "केरल (नाम परिवर्तन) अधिनियम, 2026 के तहत केरल राज्य का आधिकारिक नया नाम क्या रखा गया?", "oh": ["केरलन", "केरलम", "मलनाडु", "कैराली"], "eh": "संसद ने 11–12 अगस्त 2026 को विधेयक पास किया; राष्ट्रपति ने 14 अगस्त को मंज़ूरी दी और 25 अगस्त 2026 से 'केरलम' नाम लागू हुआ।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "A Money Bill can be introduced only in:", "o": ["The Rajya Sabha", "The Lok Sabha", "Either House", "A joint sitting of both Houses"], "a": 1, "e": "Under Article 109, a Money Bill can be introduced only in the Lok Sabha, on the President's recommendation.", "qh": "धन विधेयक (मनी बिल) केवल कहाँ पेश किया जा सकता है?", "oh": ["राज्यसभा", "लोकसभा", "किसी भी सदन", "दोनों सदनों की संयुक्त बैठक"], "eh": "अनुच्छेद 109 के तहत धन विधेयक राष्ट्रपति की सिफ़ारिश पर केवल लोकसभा में पेश होता है।", "level": "medium"}, {"s": "General Awareness", "t": "Computer", "q": "Which of the following is a web browser?", "o": ["Google Chrome", "Microsoft Windows", "Microsoft Excel", "Linux"], "a": 0, "e": "Chrome is a browser; Windows and Linux are operating systems; Excel is a spreadsheet program.", "qh": "इनमें से कौन-सा वेब ब्राउज़र है?", "oh": ["गूगल क्रोम", "माइक्रोसॉफ़्ट विंडोज़", "माइक्रोसॉफ़्ट एक्सेल", "लिनक्स"], "eh": "क्रोम ब्राउज़र है; विंडोज़ और लिनक्स ऑपरेटिंग सिस्टम हैं; एक्सेल स्प्रेडशीट प्रोग्राम है।", "level": "easy"}, {"s": "General Awareness", "t": "Geography", "q": "Which of these rivers flows westward into the Arabian Sea?", "o": ["Mahanadi", "Krishna", "Tapi", "Kaveri"], "a": 2, "e": "The Narmada and Tapi flow west into the Arabian Sea; Mahanadi, Krishna and Kaveri flow east into the Bay of Bengal.", "qh": "इनमें से कौन-सी नदी पश्चिम की ओर बहकर अरब सागर में गिरती है?", "oh": ["महानदी", "कृष्णा", "तापी", "कावेरी"], "eh": "नर्मदा और तापी पश्चिम की ओर बहकर अरब सागर में गिरती हैं; महानदी, कृष्णा और कावेरी पूर्व में बंगाल की खाड़ी में।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "Robert E. Hall and Michael Woodford won the 2026 Prize in Economic Sciences (in memory of Alfred Nobel) for:", "o": ["Research on poverty alleviation through field experiments", "Microeconomic foundations of macroeconomic stabilisation", "Theory of innovation-driven economic growth", "Study of how institutions shape prosperity"], "a": 1, "e": "The 2026 economics prize went to Hall and Woodford 'for microeconomic foundations of macroeconomic stabilisation'.", "qh": "रॉबर्ट ई. हॉल और माइकल वुडफ़ोर्ड को 2026 का अर्थशास्त्र पुरस्कार (अल्फ़्रेड नोबेल की याद में) किस काम के लिए मिला?", "oh": ["फ़ील्ड प्रयोगों से ग़रीबी घटाने पर शोध", "मैक्रोइकोनॉमिक स्थिरीकरण की माइक्रोइकोनॉमिक नींव", "नवाचार से होने वाली आर्थिक वृद्धि का सिद्धांत", "संस्थाएँ समृद्धि को कैसे बनाती हैं, इस पर अध्ययन"], "eh": "2026 का अर्थशास्त्र पुरस्कार हॉल और वुडफ़ोर्ड को 'मैक्रोइकोनॉमिक स्थिरीकरण की माइक्रोइकोनॉमिक नींव' के लिए मिला।", "level": "tough"}, {"s": "General Awareness", "t": "Current Affairs", "q": "The 'Pradhan Mantri Viksit Gram Swaraj Yojana', approved by the Union Cabinet on 28 October 2026, mainly aims to strengthen:", "o": ["Rural housing construction", "Panchayat planning, audits and governance", "Crop insurance for farmers", "Rural road connectivity"], "a": 1, "e": "The centrally sponsored scheme (2026-27 to 2030-31, about ₹7,395 crore) supports panchayat planning, audits, capacity building and accountability.", "qh": "28 अक्टूबर 2026 को केंद्रीय कैबिनेट से मंज़ूर 'प्रधानमंत्री विकसित ग्राम स्वराज योजना' का मुख्य उद्देश्य किसे मज़बूत करना है?", "oh": ["गाँवों में मकान बनाना", "पंचायतों की योजना, ऑडिट और कामकाज", "किसानों का फ़सल बीमा", "गाँवों की सड़कें"], "eh": "यह केंद्र प्रायोजित योजना (2026-27 से 2030-31, लगभग ₹7,395 करोड़) पंचायतों की योजना, ऑडिट, क्षमता निर्माण और जवाबदेही में मदद करती है।", "level": "tough"}, {"s": "General Awareness", "t": "Geography", "q": "The Hirakud Dam is built on which river?", "o": ["Godavari", "Damodar", "Subarnarekha", "Mahanadi"], "a": 3, "e": "Hirakud Dam near Sambalpur, Odisha, on the Mahanadi is one of the longest earthen dams in the world.", "qh": "हीराकुंड बाँध किस नदी पर बना है?", "oh": ["गोदावरी", "दामोदर", "सुवर्णरेखा", "महानदी"], "eh": "ओडिशा के संबलपुर के पास महानदी पर बना हीराकुंड दुनिया के सबसे लंबे मिट्टी के बाँधों में से एक है।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Which state is called the 'Spice Garden of India'?", "o": ["Karnataka", "Kerala", "Assam", "Goa"], "a": 1, "e": "Kerala grows large amounts of pepper, cardamom and other spices, earning this name.", "qh": "किस राज्य को 'भारत का मसाला बाग़' कहा जाता है?", "oh": ["कर्नाटक", "केरल", "असम", "गोवा"], "eh": "केरल में काली मिर्च, इलायची और दूसरे मसाले बहुत उगते हैं, इसलिए उसे यह नाम मिला।", "level": "easy"}, {"s": "General Awareness", "t": "Sports", "q": "The term 'googly' is used in which sport?", "o": ["Football", "Hockey", "Badminton", "Cricket"], "a": 3, "e": "A googly is a leg-spinner's delivery that turns the 'wrong' way.", "qh": "'गुगली' शब्द किस खेल में इस्तेमाल होता है?", "oh": ["फ़ुटबॉल", "हॉकी", "बैडमिंटन", "क्रिकेट"], "eh": "गुगली लेग स्पिनर की ऐसी गेंद है जो उल्टी दिशा में घूमती है।", "level": "easy"}, {"s": "General Awareness", "t": "Geography", "q": "Majuli, one of the world's largest river islands, lies in which river?", "o": ["Brahmaputra", "Ganga", "Godavari", "Indus"], "a": 0, "e": "Majuli in Assam lies in the Brahmaputra and became India's first island district in 2016.", "qh": "दुनिया के सबसे बड़े नदी द्वीपों में से एक माजुली किस नदी में है?", "oh": ["ब्रह्मपुत्र", "गंगा", "गोदावरी", "सिंधु"], "eh": "असम का माजुली ब्रह्मपुत्र नदी में है और 2016 में भारत का पहला द्वीप ज़िला बना।", "level": "tough"}, {"s": "General Awareness", "t": "Polity", "q": "The right to free and compulsory education under Article 21A covers children of which age group?", "o": ["5 to 15 years", "6 to 14 years", "3 to 12 years", "6 to 18 years"], "a": 1, "e": "Article 21A (86th Amendment, 2002) makes education a Fundamental Right for children aged 6–14.", "qh": "अनुच्छेद 21A के तहत मुफ़्त और अनिवार्य शिक्षा का अधिकार किस उम्र के बच्चों के लिए है?", "oh": ["5 से 15 साल", "6 से 14 साल", "3 से 12 साल", "6 से 18 साल"], "eh": "अनुच्छेद 21A (86वाँ संशोधन, 2002) 6–14 साल के बच्चों की शिक्षा को मौलिक अधिकार बनाता है।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Emperor Ashoka gave up war and turned to Buddhism after which war?", "o": ["Battle of Hydaspes", "Battle of Plassey", "First Battle of Tarain", "Kalinga War"], "a": 3, "e": "The bloodshed of the Kalinga War (c. 261 BCE) changed Ashoka's heart.", "qh": "सम्राट अशोक ने किस युद्ध के बाद लड़ाई छोड़कर बौद्ध धर्म अपनाया?", "oh": ["हाइडेस्पीज़ की लड़ाई", "प्लासी की लड़ाई", "तराइन की पहली लड़ाई", "कलिंग युद्ध"], "eh": "कलिंग युद्ध (लगभग 261 ई.पू.) के ख़ून-ख़राबे ने अशोक का मन बदल दिया।", "level": "easy"}, {"s": "General Awareness", "t": "General Science", "q": "Which gas makes up the largest part of the Earth's atmosphere?", "o": ["Oxygen", "Carbon dioxide", "Nitrogen", "Argon"], "a": 2, "e": "Dry air is about 78% nitrogen and 21% oxygen.", "qh": "पृथ्वी के वायुमंडल में सबसे ज़्यादा कौन-सी गैस है?", "oh": ["ऑक्सीजन", "कार्बन डाइऑक्साइड", "नाइट्रोजन", "आर्गन"], "eh": "सूखी हवा में लगभग 78% नाइट्रोजन और 21% ऑक्सीजन होती है।", "level": "easy"}, {"s": "General Awareness", "t": "General Science", "q": "Which instrument records earthquakes?", "o": ["Seismograph", "Barometer", "Hygrometer", "Altimeter"], "a": 0, "e": "A seismograph records ground vibrations; barometer = air pressure, hygrometer = humidity, altimeter = height.", "qh": "भूकंप को कौन-सा यंत्र रिकॉर्ड करता है?", "oh": ["सिस्मोग्राफ़ (भूकंपलेखी)", "बैरोमीटर", "हाइग्रोमीटर", "अल्टीमीटर"], "eh": "सिस्मोग्राफ़ ज़मीन के कंपन रिकॉर्ड करता है; बैरोमीटर = वायुदाब, हाइग्रोमीटर = नमी, अल्टीमीटर = ऊँचाई।", "level": "easy"}, {"s": "General Awareness", "t": "Sports", "q": "Who won the women's singles title at the French Open (Roland-Garros) 2026?", "o": ["Iga Świątek", "Coco Gauff", "Mirra Andreeva", "Aryna Sabalenka"], "a": 2, "e": "Mirra Andreeva beat Maja Chwalińska 6-3, 6-2 for her first Grand Slam title; Alexander Zverev won the men's title.", "qh": "फ़्रेंच ओपन (रोलां गैरो) 2026 का महिला एकल ख़िताब किसने जीता?", "oh": ["इगा श्वियोंतेक", "कोको गॉफ़", "मिर्रा आंद्रेयेवा", "आर्यना सबालेंका"], "eh": "मिर्रा आंद्रेयेवा ने माया ख़्वालिंस्का को 6-3, 6-2 से हराकर अपना पहला ग्रैंड स्लैम जीता; पुरुष ख़िताब अलेक्ज़ेंडर ज़्वेरेव ने जीता।", "level": "medium"}, {"s": "General Awareness", "t": "Awards", "q": "Tamil poet and lyricist R. Vairamuthu was named for which award in March 2026 (its 60th edition)?", "o": ["Sahitya Akademi Fellowship", "Jnanpith Award", "Saraswati Samman", "Vyas Samman"], "a": 1, "e": "Bharatiya Jnanpith announced on 14 March 2026 that Vairamuthu would get the 60th Jnanpith Award; he is the third Tamil writer to win it.", "qh": "तमिल कवि और गीतकार आर. वैरमुत्तु को मार्च 2026 में कौन-सा पुरस्कार (60वाँ) देने की घोषणा हुई?", "oh": ["साहित्य अकादमी फ़ेलोशिप", "ज्ञानपीठ पुरस्कार", "सरस्वती सम्मान", "व्यास सम्मान"], "eh": "भारतीय ज्ञानपीठ ने 14 मार्च 2026 को वैरमुत्तु को 60वाँ ज्ञानपीठ पुरस्कार देने की घोषणा की; वे यह पाने वाले तीसरे तमिल लेखक हैं।", "level": "medium"}, {"s": "General Awareness", "t": "Computer", "q": "What does 'HTTP' stand for?", "o": ["HyperText Transfer Protocol", "High Transfer Text Process", "Hyperlink Text Transmission Program", "Home Tool Transfer Protocol"], "a": 0, "e": "HTTP is the protocol used to transfer web pages.", "qh": "'HTTP' का पूरा नाम क्या है?", "oh": ["HyperText Transfer Protocol", "High Transfer Text Process", "Hyperlink Text Transmission Program", "Home Tool Transfer Protocol"], "eh": "HTTP वेब पेज भेजने-लाने का प्रोटोकॉल है।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "The Gol Gumbaz at Bijapur (Vijayapura) is the tomb of:", "o": ["Ibrahim Qutb Shah", "Ahmad Shah Bahmani", "Muhammad Adil Shah", "Malik Ambar"], "a": 2, "e": "Gol Gumbaz (completed 1656) is the tomb of Muhammad Adil Shah of the Adil Shahi dynasty.", "qh": "बीजापुर (विजयपुरा) का गोल गुंबज किसका मकबरा है?", "oh": ["इब्राहिम क़ुतुब शाह", "अहमद शाह बहमनी", "मुहम्मद आदिल शाह", "मलिक अंबर"], "eh": "गोल गुंबज (1656 में पूरा) आदिलशाही वंश के मुहम्मद आदिल शाह का मकबरा है।", "level": "tough"}, {"s": "General Awareness", "t": "General Science", "q": "Which mirror do dentists use to see an enlarged image of the teeth?", "o": ["Convex mirror", "Plane mirror", "Cylindrical mirror", "Concave mirror"], "a": 3, "e": "A concave mirror held close to the teeth gives an enlarged, erect image.", "qh": "दाँतों का बड़ा प्रतिबिंब देखने के लिए दंत चिकित्सक कौन-सा दर्पण इस्तेमाल करते हैं?", "oh": ["उत्तल दर्पण", "समतल दर्पण", "बेलनाकार दर्पण", "अवतल दर्पण"], "eh": "दाँतों के पास रखा अवतल दर्पण बड़ा, सीधा प्रतिबिंब देता है।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "The sky looks blue mainly because of:", "o": ["Scattering of sunlight", "Reflection of sunlight by the sea", "Refraction of sunlight", "Total internal reflection"], "a": 0, "e": "Air molecules scatter shorter (blue) wavelengths of sunlight much more than red ones.", "qh": "आसमान मुख्य रूप से किस कारण नीला दिखता है?", "oh": ["सूरज की रोशनी के प्रकीर्णन (बिखरने) से", "समुद्र से रोशनी के परावर्तन से", "रोशनी के अपवर्तन से", "पूर्ण आंतरिक परावर्तन से"], "eh": "हवा के अणु सूरज की रोशनी की छोटी (नीली) तरंगों को लाल के मुक़ाबले बहुत ज़्यादा बिखेरते हैं।", "level": "tough"}, {"s": "General Awareness", "t": "Polity", "q": "Who administers the oath of office to the Governor of a state?", "o": ["The President", "The Chief Minister", "The Speaker of the state Assembly", "The Chief Justice of the High Court of that state"], "a": 3, "e": "Under Article 159, the Chief Justice of the state's High Court (or the senior-most judge) administers the oath to the Governor.", "qh": "किसी राज्य के राज्यपाल को पद की शपथ कौन दिलाता है?", "oh": ["राष्ट्रपति", "मुख्यमंत्री", "विधानसभा अध्यक्ष", "उस राज्य के हाई कोर्ट के मुख्य न्यायाधीश"], "eh": "अनुच्छेद 159 के तहत राज्य के हाई कोर्ट के मुख्य न्यायाधीश (या सबसे वरिष्ठ जज) राज्यपाल को शपथ दिलाते हैं।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Who founded the Ramakrishna Mission in 1897?", "o": ["Ramakrishna Paramahamsa", "Swami Dayanand Saraswati", "Sri Aurobindo", "Swami Vivekananda"], "a": 3, "e": "Swami Vivekananda founded the Ramakrishna Mission in 1897, named after his guru.", "qh": "1897 में रामकृष्ण मिशन की स्थापना किसने की?", "oh": ["रामकृष्ण परमहंस", "स्वामी दयानंद सरस्वती", "श्री अरविंद", "स्वामी विवेकानंद"], "eh": "स्वामी विवेकानंद ने 1897 में अपने गुरु के नाम पर रामकृष्ण मिशन बनाया।", "level": "easy"}, {"s": "General Awareness", "t": "Geography", "q": "Sambhar, India's largest inland saline lake, is in which state?", "o": ["Gujarat", "Rajasthan", "Haryana", "Madhya Pradesh"], "a": 1, "e": "Sambhar Lake near Jaipur in Rajasthan is the largest inland salt lake and a major salt source.", "qh": "भारत की सबसे बड़ी अंतर्देशीय खारे पानी की झील सांभर किस राज्य में है?", "oh": ["गुजरात", "राजस्थान", "हरियाणा", "मध्य प्रदेश"], "eh": "जयपुर के पास राजस्थान की सांभर झील सबसे बड़ी अंतर्देशीय नमक झील है और नमक का बड़ा स्रोत है।", "level": "medium"}, {"s": "General Awareness", "t": "Science & Tech", "q": "Where is the headquarters of ISRO?", "o": ["Sriharikota", "Bengaluru", "Thiruvananthapuram", "Ahmedabad"], "a": 1, "e": "ISRO is headquartered at Antariksh Bhavan, Bengaluru; Sriharikota is its launch centre.", "qh": "इसरो (ISRO) का मुख्यालय कहाँ है?", "oh": ["श्रीहरिकोटा", "बेंगलुरु", "तिरुवनंतपुरम", "अहमदाबाद"], "eh": "इसरो का मुख्यालय बेंगलुरु के अंतरिक्ष भवन में है; श्रीहरिकोटा उसका प्रक्षेपण केंद्र है।", "level": "easy"}, {"s": "General Awareness", "t": "General Science", "q": "Which organ of the human body produces insulin?", "o": ["Liver", "Kidney", "Pancreas", "Thyroid"], "a": 2, "e": "The beta cells of the islets of Langerhans in the pancreas make insulin, which lowers blood sugar.", "qh": "मानव शरीर में इंसुलिन कौन-सा अंग बनाता है?", "oh": ["यकृत (लिवर)", "गुर्दा", "अग्न्याशय (पैंक्रियास)", "थायरॉइड"], "eh": "अग्न्याशय के लैंगरहैंस द्वीपों की बीटा कोशिकाएँ इंसुलिन बनाती हैं, जो खून में शुगर घटाता है।", "level": "medium"}, {"s": "General Awareness", "t": "Railways", "q": "In which year was the Darjeeling Himalayan Railway declared a UNESCO World Heritage Site?", "o": ["2005", "2008", "1999", "1987"], "a": 2, "e": "The Darjeeling Himalayan Railway was inscribed in 1999; the Nilgiri (2005) and Kalka–Shimla (2008) lines were added later as 'Mountain Railways of India'.", "qh": "दार्जिलिंग हिमालयन रेलवे को यूनेस्को विश्व धरोहर किस साल घोषित किया गया?", "oh": ["2005", "2008", "1999", "1987"], "eh": "दार्जिलिंग हिमालयन रेलवे 1999 में शामिल हुई; नीलगिरि (2005) और कालका–शिमला (2008) लाइनें बाद में 'भारत की पर्वतीय रेलें' के रूप में जुड़ीं।", "level": "tough"}, {"s": "General Awareness", "t": "Polity", "q": "What is the maximum gap allowed between two sessions of Parliament?", "o": ["Three months", "Nine months", "One year", "Six months"], "a": 3, "e": "Article 85 says Parliament must meet at least once in six months.", "qh": "संसद के दो सत्रों के बीच ज़्यादा से ज़्यादा कितना अंतर हो सकता है?", "oh": ["तीन महीने", "नौ महीने", "एक साल", "छह महीने"], "eh": "अनुच्छेद 85 के अनुसार संसद को छह महीने में कम से कम एक बार बैठना ज़रूरी है।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "Which body regulates the insurance sector in India?", "o": ["SEBI", "PFRDA", "NABARD", "IRDAI"], "a": 3, "e": "The Insurance Regulatory and Development Authority of India (IRDAI) regulates insurance; SEBI regulates markets, PFRDA pensions.", "qh": "भारत में बीमा क्षेत्र का नियामक (रेगुलेटर) कौन है?", "oh": ["SEBI", "PFRDA", "NABARD", "IRDAI"], "eh": "बीमा का नियमन IRDAI करता है; SEBI शेयर बाज़ार का और PFRDA पेंशन का नियामक है।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Who founded the Brahmo Samaj in 1828?", "o": ["Raja Ram Mohan Roy", "Debendranath Tagore", "Keshab Chandra Sen", "Ishwar Chandra Vidyasagar"], "a": 0, "e": "Raja Ram Mohan Roy founded the Brahmo Sabha (later Brahmo Samaj) in Calcutta in 1828.", "qh": "1828 में ब्रह्म समाज की स्थापना किसने की?", "oh": ["राजा राममोहन राय", "देवेंद्रनाथ टैगोर", "केशव चंद्र सेन", "ईश्वरचंद्र विद्यासागर"], "eh": "राजा राममोहन राय ने 1828 में कलकत्ता में ब्रह्म सभा (बाद में ब्रह्म समाज) बनाई।", "level": "medium"}, {"s": "General Awareness", "t": "Static GK", "q": "Which city is known as the 'Pink City' of India?", "o": ["Jodhpur", "Udaipur", "Bhopal", "Jaipur"], "a": 3, "e": "Jaipur's old city buildings were painted pink in 1876 to welcome the Prince of Wales.", "qh": "भारत का 'गुलाबी शहर' (पिंक सिटी) किसे कहा जाता है?", "oh": ["जोधपुर", "उदयपुर", "भोपाल", "जयपुर"], "eh": "1876 में प्रिंस ऑफ़ वेल्स के स्वागत में जयपुर के पुराने शहर की इमारतें गुलाबी रंगी गईं।", "level": "easy"}, {"s": "General Awareness", "t": "Static GK", "q": "India's national flower — the flower after which the Padma awards are named — is the:", "o": ["Rose", "Lotus", "Marigold", "Jasmine"], "a": 1, "e": "The lotus (padma) is India's national flower; the Padma Vibhushan, Padma Bhushan and Padma Shri are named after it.", "qh": "भारत का राष्ट्रीय फूल — जिसके नाम पर पद्म पुरस्कार रखे गए हैं — कौन-सा है?", "oh": ["गुलाब", "कमल", "गेंदा", "चमेली"], "eh": "कमल (पद्म) भारत का राष्ट्रीय फूल है; पद्म विभूषण, पद्म भूषण और पद्म श्री इसी के नाम पर हैं।", "level": "easy"}, {"s": "General Awareness", "t": "Art & Culture", "q": "The Konark Sun Temple is in which state?", "o": ["West Bengal", "Odisha", "Andhra Pradesh", "Madhya Pradesh"], "a": 1, "e": "The 13th-century Sun Temple at Konark, built by King Narasimhadeva I, is in Odisha.", "qh": "कोणार्क का सूर्य मंदिर किस राज्य में है?", "oh": ["पश्चिम बंगाल", "ओडिशा", "आंध्र प्रदेश", "मध्य प्रदेश"], "eh": "13वीं सदी का कोणार्क सूर्य मंदिर, जिसे राजा नरसिंहदेव प्रथम ने बनवाया, ओडिशा में है।", "level": "easy"}, {"s": "General Awareness", "t": "Polity", "q": "Which Schedule of the Constitution contains the anti-defection provisions?", "o": ["Ninth Schedule", "Eighth Schedule", "Tenth Schedule", "Seventh Schedule"], "a": 2, "e": "The Tenth Schedule was added by the 52nd Amendment (1985) to check defection by legislators.", "qh": "दल-बदल विरोधी प्रावधान संविधान की किस अनुसूची में हैं?", "oh": ["नौवीं अनुसूची", "आठवीं अनुसूची", "दसवीं अनुसूची", "सातवीं अनुसूची"], "eh": "विधायकों के दल-बदल रोकने के लिए 52वें संशोधन (1985) से दसवीं अनुसूची जोड़ी गई।", "level": "tough"}, {"s": "General Awareness", "t": "History", "q": "The Revolt of 1857 began on 10 May 1857 at:", "o": ["Meerut", "Delhi", "Kanpur", "Lucknow"], "a": 0, "e": "Sepoys at Meerut rose on 10 May 1857 and marched to Delhi, where Bahadur Shah Zafar was declared emperor.", "qh": "1857 का विद्रोह 10 मई 1857 को कहाँ से शुरू हुआ?", "oh": ["मेरठ", "दिल्ली", "कानपुर", "लखनऊ"], "eh": "10 मई 1857 को मेरठ के सिपाहियों ने विद्रोह किया और दिल्ली की ओर बढ़े, जहाँ बहादुर शाह ज़फ़र को बादशाह घोषित किया गया।", "level": "medium"}, {"s": "General Awareness", "t": "Awards", "q": "The Dronacharya Award is given to:", "o": ["Best school teachers", "Defence scientists", "Outstanding sports coaches", "Classical musicians"], "a": 2, "e": "The Dronacharya Award (since 1985) honours coaches who produce medal-winning sportspersons.", "qh": "द्रोणाचार्य पुरस्कार किसे दिया जाता है?", "oh": ["सबसे अच्छे स्कूल शिक्षकों", "रक्षा वैज्ञानिकों", "उत्कृष्ट खेल प्रशिक्षकों (कोच)", "शास्त्रीय संगीतकारों"], "eh": "द्रोणाचार्य पुरस्कार (1985 से) उन कोचों को मिलता है जिनके खिलाड़ी पदक जीतते हैं।", "level": "medium"}, {"s": "General Awareness", "t": "Art & Culture", "q": "Mohiniyattam is a classical dance of which state?", "o": ["Karnataka", "Tamil Nadu", "Kerala", "Andhra Pradesh"], "a": 2, "e": "Mohiniyattam, a graceful solo dance traditionally by women, is from Kerala.", "qh": "मोहिनीअट्टम किस राज्य का शास्त्रीय नृत्य है?", "oh": ["कर्नाटक", "तमिलनाडु", "केरल", "आंध्र प्रदेश"], "eh": "मोहिनीअट्टम, जो पारंपरिक रूप से महिलाएँ अकेले करती हैं, केरल का नृत्य है।", "level": "medium"}, {"s": "Mathematics", "t": "Number System", "q": "What is the greatest number that divides 780, 306 and 1371, leaving remainders 3, 10 and 2 respectively?", "o": ["41", "75", "35", "37"], "a": 3, "e": "Subtract the remainders: 777, 296, 1369. HCF = 37.", "qh": "वह सबसे बड़ी संख्या कौन-सी है जिससे 780, 306 और 1371 को भाग देने पर क्रमशः 3, 10 और 2 शेष बचें?", "oh": ["41", "75", "35", "37"], "eh": "शेषफल घटाएँ: 777, 296, 1369। HCF = 37।", "level": "tough"}, {"s": "Mathematics", "t": "Number System", "q": "The HCF of two numbers is 18 and their LCM is 324. If one of the numbers is 36, what is the other number?", "o": ["54", "18", "180", "162"], "a": 3, "e": "Product of numbers = HCF × LCM → other = 18 × 324/36 = 162.", "qh": "दो संख्याओं का HCF 18 और LCM 324 है। अगर एक संख्या 36 है, तो दूसरी संख्या क्या है?", "oh": ["54", "18", "180", "162"], "eh": "संख्याओं का गुणनफल = HCF × LCM → दूसरी = 18 × 324/36 = 162।", "level": "tough"}, {"s": "Mathematics", "t": "Interest", "q": "What is the simple interest on ₹15,000 at 12.5% per annum for 4 years?", "o": ["₹9,375", "₹22,500", "₹7,500", "₹1,875"], "a": 2, "e": "SI = P × R × T/100 = 15000 × 12.5 × 4/100 = ₹7,500.", "qh": "₹15,000 पर 12.5% वार्षिक दर से 4 साल का साधारण ब्याज कितना होगा?", "oh": ["₹9,375", "₹22,500", "₹7,500", "₹1,875"], "eh": "साधारण ब्याज = P × R × T/100 = 15000 × 12.5 × 4/100 = ₹7,500।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "An article is sold at a loss of 8%. If it had been sold for ₹300 more, there would have been a gain of 12%. What is the cost price of the article?", "o": ["₹1,400", "₹1,700", "₹1,500", "₹7,500"], "a": 2, "e": "(8 + 12)% of CP = ₹300 → CP = ₹300 × 100/20 = ₹1,500.", "qh": "एक वस्तु 8% हानि पर बेची गई। अगर उसे ₹300 ज़्यादा में बेचा जाता, तो 12% लाभ होता। वस्तु का क्रय मूल्य क्या है?", "oh": ["₹1,400", "₹1,700", "₹1,500", "₹7,500"], "eh": "क्रय मूल्य का (8 + 12)% = ₹300 → क्रय मूल्य = ₹300 × 100/20 = ₹1,500।", "level": "easy"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "The incomes of Karan and Seema are in the ratio 9 : 7 and their expenditures are in the ratio 4 : 3. If each of them saves ₹1,000, what is Karan's income?", "o": ["₹9,000", "₹7,000", "₹10,000", "₹8,000"], "a": 0, "e": "9x − 4y = 7x − 3y = 1000 → 2x = 1y. Solving: x = 1000, y = 2000, so income = 9 × 1000 = ₹9,000.", "qh": "करण और सीमा की आय का अनुपात 9 : 7 और खर्च का अनुपात 4 : 3 है। अगर दोनों ₹1,000 बचाते हैं, तो करण की आय कितनी है?", "oh": ["₹9,000", "₹7,000", "₹10,000", "₹8,000"], "eh": "9x − 4y = 7x − 3y = 1000 → 2x = 1y। हल करने पर x = 1000, y = 2000, आय = 9 × 1000 = ₹9,000।", "level": "tough"}, {"s": "Mathematics", "t": "Ages", "q": "The present ages of Naveen and Priya are in the ratio 4 : 5. After 10 years, the ratio will be 46 : 55. What is Priya's present age?", "o": ["71 years", "55 years", "45 years", "35 years"], "a": 2, "e": "(4x + 10)/(5x + 10) = 46/55 → x = 9; age = 5 × 9 = 45 years.", "qh": "नवीन और प्रिया की अभी की आयु का अनुपात 4 : 5 है। 10 साल बाद यह अनुपात 46 : 55 हो जाएगा। प्रिया की अभी की आयु कितनी है?", "oh": ["71 साल", "55 साल", "45 साल", "35 साल"], "eh": "(4x + 10)/(5x + 10) = 46/55 → x = 9; आयु = 5 × 9 = 45 साल।", "level": "medium"}, {"s": "Mathematics", "t": "Algebra", "q": "If a + b = 24 and ab = 140, what is a³ + b³?", "o": ["23904", "10464", "3744", "13824"], "a": 2, "e": "a³ + b³ = (a + b)³ − 3ab(a + b) = 13824 − 10080 = 3744.", "qh": "अगर a + b = 24 और ab = 140 है, तो a³ + b³ का मान क्या है?", "oh": ["23904", "10464", "3744", "13824"], "eh": "a³ + b³ = (a + b)³ − 3ab(a + b) = 13824 − 10080 = 3744।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "An amount is divided among Arjun, Deepak and Ritu in the ratio 3 : 5 : 7. If Ritu gets ₹2,400 more than Arjun, what is Deepak's share?", "o": ["₹6,000", "₹3,000", "₹1,800", "₹3,600"], "a": 1, "e": "(7 − 3) parts = ₹2,400 → 1 part = ₹600; Deepak = 5 × ₹600 = ₹3,000.", "qh": "एक रकम को अर्जुन, दीपक और रितु में 3 : 5 : 7 के अनुपात में बाँटा गया। अगर रितु को अर्जुन से ₹2,400 ज़्यादा मिलते हैं, तो दीपक का हिस्सा कितना है?", "oh": ["₹6,000", "₹3,000", "₹1,800", "₹3,600"], "eh": "(7 − 3) भाग = ₹2,400 → 1 भाग = ₹600; दीपक = 5 × ₹600 = ₹3,000।", "level": "medium"}, {"s": "Mathematics", "t": "Mensuration", "q": "What is the volume of a cone with radius 3.5 cm and height 15 cm? (Take π = 22/7)", "o": ["385 cm³", "192.5 cm³", "96.25 cm³", "214.5 cm³"], "a": 1, "e": "⅓πr²h = ⅓ × 22/7 × 3.5² × 15 = 192.5 cm³.", "qh": "3.5 cm त्रिज्या और ऊँचाई 15 cm वाले शंकु का आयतन कितना है? (π = 22/7 लें)", "oh": ["385 cm³", "192.5 cm³", "96.25 cm³", "214.5 cm³"], "eh": "⅓πr²h = ⅓ × 22/7 × 3.5² × 15 = 192.5 cm³।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A shopkeeper marks an article 25% above its cost price and allows a discount of 15%. What is his profit percentage?", "o": ["3.75%", "10%", "8.25%", "6.25%"], "a": 3, "e": "SP/CP = 1.25 × 0.85 = 17/16 → profit = 6.25%.", "qh": "एक दुकानदार वस्तु पर क्रय मूल्य से 25% ज़्यादा दाम लिखता है और 15% छूट देता है। उसका लाभ प्रतिशत क्या है?", "oh": ["3.75%", "10%", "8.25%", "6.25%"], "eh": "विक्रय/क्रय = 1.25 × 0.85 = 17/16 → लाभ = 6.25%।", "level": "medium"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A bus goes from town P to town Q at 45 km/h and returns along the same road at 90 km/h. What is its average speed for the whole journey?", "o": ["60 km/h", "45 km/h", "67.5 km/h", "57 km/h"], "a": 0, "e": "Average speed = 2ab/(a + b) = 2 × 45 × 90/135 = 60 km/h.", "qh": "एक बस कस्बे P से कस्बे Q तक 45 km/h की रफ़्तार से जाती है और उसी रास्ते से 90 km/h की रफ़्तार से लौटती है। पूरे सफ़र में उसकी औसत रफ़्तार क्या है?", "oh": ["60 km/h", "45 km/h", "67.5 km/h", "57 km/h"], "eh": "औसत रफ़्तार = 2ab/(a + b) = 2 × 45 × 90/135 = 60 km/h।", "level": "easy"}, {"s": "Mathematics", "t": "Percentage", "q": "In an examination, a student who scores 32% marks fails by 20 marks, while another student who scores 42% marks gets 100 marks more than the pass marks. What are the maximum marks?", "o": ["1250", "1200", "1400", "1300"], "a": 1, "e": "(42 − 32)% of maximum = 20 + 100 = 120 → maximum = 120 × 100/10 = 1200.", "qh": "एक परीक्षा में 32% अंक पाने वाला छात्र 20 अंकों से फ़ेल होता है, जबकि 42% अंक पाने वाले छात्र को पास अंकों से 100 अंक ज़्यादा मिलते हैं। पूरे अंक कितने हैं?", "oh": ["1250", "1200", "1400", "1300"], "eh": "पूरे अंकों का (42 − 32)% = 20 + 100 = 120 → पूरे अंक = 120 × 100/10 = 1200।", "level": "medium"}, {"s": "Mathematics", "t": "Percentage", "q": "The population of a town is 80,000. It increases by 5% in the first year and decreases by 5% in the second year. What is the population after 2 years?", "o": ["84,000", "79,900", "79,800", "79,600"], "a": 2, "e": "80,000 × 1.05 × 0.95 = 79,800.", "qh": "एक कस्बे की आबादी 80,000 है। यह पहले साल 5% बढ़ती है और दूसरे साल 5% घटती है। 2 साल बाद आबादी कितनी होगी?", "oh": ["84,000", "79,900", "79,800", "79,600"], "eh": "80,000 × 1.05 × 0.95 = 79,800।", "level": "tough"}, {"s": "Mathematics", "t": "Mensuration", "q": "A solid metal sphere of radius 15 cm is melted and recast into small spheres of radius 1 cm each. How many small spheres are formed?", "o": ["6750", "15", "225", "3375"], "a": 3, "e": "Number = (R/r)³ = (15/1)³ = 3375.", "qh": "15 cm त्रिज्या वाले धातु के ठोस गोले को पिघलाकर 1 cm त्रिज्या वाले छोटे गोले बनाए जाते हैं। कितने छोटे गोले बनेंगे?", "oh": ["6750", "15", "225", "3375"], "eh": "संख्या = (R/r)³ = (15/1)³ = 3375।", "level": "tough"}, {"s": "Mathematics", "t": "Interest", "q": "The difference between compound interest and simple interest on a sum for 3 years at 20% per annum is ₹1,024. What is the sum?", "o": ["₹7,000", "₹16,000", "₹8,000", "₹5,120"], "a": 2, "e": "CI − SI = P[(1 + 20/100)^3 − 1 − 3 × 20/100] = 16/125 × P = ₹1,024 → P = ₹8,000.", "qh": "किसी रकम पर 20% वार्षिक दर से 3 साल के चक्रवृद्धि ब्याज और साधारण ब्याज का अंतर ₹1,024 है। रकम कितनी है?", "oh": ["₹7,000", "₹16,000", "₹8,000", "₹5,120"], "eh": "CI − SI = P[(1 + 20/100)^3 − 1 − 3 × 20/100] = 16/125 × P = ₹1,024 → P = ₹8,000।", "level": "medium"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average weight of 15 persons increases by 1 kg when a person weighing 45 kg is replaced by a new person. What is the weight of the new person?", "o": ["46 kg", "60 kg", "30 kg", "75 kg"], "a": 1, "e": "Total increase = 15 × 1 = 15 kg. New = 45 + 15 = 60 kg.", "qh": "15 लोगों का औसत वज़न 1 kg बढ़ जाता है, जब 45 kg वज़न वाले एक व्यक्ति की जगह कोई नया व्यक्ति आता है। नए व्यक्ति का वज़न कितना है?", "oh": ["46 kg", "60 kg", "30 kg", "75 kg"], "eh": "कुल बढ़ोतरी = 15 × 1 = 15 kg। नया = 45 + 15 = 60 kg।", "level": "tough"}, {"s": "Mathematics", "t": "Number System", "q": "What is the largest 4-digit number which, when divided by 10, 12 and 15, leaves a remainder of 4 in each case?", "o": ["9968", "9904", "9960", "9964"], "a": 3, "e": "LCM = 60. The required number is a multiple of 60 plus 4: 9960 + 4 = 9964.", "qh": "4 अंकों की वह सबसे बड़ी संख्या कौन-सी है जिसे 10, 12 और 15 से भाग देने पर हर बार 4 शेष बचे?", "oh": ["9968", "9904", "9960", "9964"], "eh": "LCM = 60। चाहिए: 60 का गुणज + 4: 9960 + 4 = 9964।", "level": "tough"}, {"s": "Mathematics", "t": "Simplification", "q": "What is the value of 44² − 25²?", "o": ["1311", "2622", "1321", "1312"], "a": 0, "e": "a² − b² = (a + b)(a − b) = 69 × 19 = 1311.", "qh": "44² − 25² का मान क्या है?", "oh": ["1311", "2622", "1321", "1312"], "eh": "a² − b² = (a + b)(a − b) = 69 × 19 = 1311।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A dishonest grocer uses a weight of 750 g in place of 1 kg and also sells at 5% above cost price. What is his gain percentage?", "o": ["39%", "40%", "25%", "41%"], "a": 1, "e": "He gives 750 g but charges for 1000 g at 5% above cost: gain = 1000 × 1.05/750 − 1 = 40%.", "qh": "एक बेईमान दुकानदार 1 kg की जगह 750 g का बाट इस्तेमाल करता है और साथ में क्रय मूल्य से 5% ज़्यादा दाम पर बेचता है। उसका लाभ प्रतिशत क्या है?", "oh": ["39%", "40%", "25%", "41%"], "eh": "वह 750 g देता है पर 1000 g के पैसे लेता है (क्रय मूल्य से 5% ज़्यादा): लाभ = 1000 × 1.05/750 − 1 = 40%।", "level": "tough"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "Successive discounts of 20% and 10% are equivalent to a single discount of:", "o": ["28%", "29%", "26%", "30%"], "a": 0, "e": "Price left = 0.8 × 0.9 = 0.72. Single discount = 28%.", "qh": "20% और 10% की लगातार छूट किस एक छूट के बराबर हैं?", "oh": ["28%", "29%", "26%", "30%"], "eh": "बचा दाम = 0.8 × 0.9 = 0.72। एक छूट = 28%।", "level": "medium"}, {"s": "Mathematics", "t": "Geometry", "q": "What is the complement of an angle of 47°?", "o": ["43°", "53°", "313°", "133°"], "a": 0, "e": "90° − 47° = 43°.", "qh": "47° के कोण का पूरक कोण कितना है?", "oh": ["43°", "53°", "313°", "133°"], "eh": "90° − 47° = 43°।", "level": "easy"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A train running at 72 km/h crosses a pole in 8 seconds. What is the length of the train?", "o": ["320 m", "576 m", "160 m", "210 m"], "a": 2, "e": "72 km/h = 72 × 5/18 = 20 m/s. Length = 20 × 8 = 160 m.", "qh": "72 km/h की रफ़्तार से चल रही एक ट्रेन एक खंभे को 8 सेकंड में पार करती है। ट्रेन की लंबाई कितनी है?", "oh": ["320 m", "576 m", "160 m", "210 m"], "eh": "72 km/h = 72 × 5/18 = 20 m/s। लंबाई = 20 × 8 = 160 m।", "level": "easy"}, {"s": "Mathematics", "t": "Time and Work", "q": "A and B together can do a piece of work in 20 days, B and C together in 15 days, and C and A together in 12 days. In how many days can A alone finish it?", "o": ["20 days", "30 days", "47/3 days", "32 days"], "a": 1, "e": "2(A + B + C) = 1/20 + 1/15 + 1/12 → A + B + C = 1/10 per day; A = 1/10 − 1/15 = 1/30 → 30 days.", "qh": "A और B मिलकर एक काम 20 दिन में, B और C मिलकर 15 दिन में, और C और A मिलकर 12 दिन में कर सकते हैं। A अकेला वह काम कितने दिन में करेगा?", "oh": ["20 दिन", "30 दिन", "47/3 दिन", "32 दिन"], "eh": "2(A + B + C) = 1/20 + 1/15 + 1/12 → A + B + C = 1/10 प्रति दिन; A = 1/10 − 1/15 = 1/30 → 30 दिन।", "level": "tough"}, {"s": "Mathematics", "t": "Time and Work", "q": "18 workers can build a wall in 12 days. How many days will 24 workers take to build the same wall?", "o": ["9 days", "8 days", "17 days", "16 days"], "a": 0, "e": "Work = 18 × 12 = 216 worker-days. Days = 216/24 = 9.", "qh": "18 मज़दूर एक दीवार 12 दिन में बना सकते हैं। 24 मज़दूर वही दीवार कितने दिन में बनाएँगे?", "oh": ["9 दिन", "8 दिन", "17 दिन", "16 दिन"], "eh": "काम = 18 × 12 = 216 मज़दूर-दिन। दिन = 216/24 = 9।", "level": "easy"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average age of 40 students of a class is 12 years. When the teacher's age is included, the average increases by 2 years. What is the teacher's age?", "o": ["92 years", "95 years", "94 years", "82 years"], "a": 2, "e": "Teacher = new average + 40 × increase = 14 + 40 × 2 = 94 years.", "qh": "एक कक्षा के 40 छात्रों की औसत आयु 12 साल है। शिक्षक की आयु जोड़ने पर औसत 2 साल बढ़ जाता है। शिक्षक की आयु कितनी है?", "oh": ["92 साल", "95 साल", "94 साल", "82 साल"], "eh": "शिक्षक = नया औसत + 40 × बढ़ोतरी = 14 + 40 × 2 = 94 साल।", "level": "tough"}, {"s": "Mathematics", "t": "Number System", "q": "What is the unit digit of 13^35 × 4^57?", "o": ["0", "9", "2", "8"], "a": 3, "e": "Unit digit of 13^35 = 7, of 4^57 = 4. 7 × 4 → unit digit 8.", "qh": "13^35 × 4^57 का इकाई अंक क्या है?", "oh": ["0", "9", "2", "8"], "eh": "13^35 का इकाई अंक = 7, 4^57 का = 4। 7 × 4 → इकाई अंक 8।", "level": "medium"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: [17 + {12 × 21 − (24 + 30)}] ÷ 5 + 2", "o": ["42", "47", "55", "45"], "a": 3, "e": "Follow BODMAS (brackets, then ÷ and × from left to right, then + and −): value = 45.", "qh": "सरल कीजिए: [17 + {12 × 21 − (24 + 30)}] ÷ 5 + 2", "oh": ["42", "47", "55", "45"], "eh": "BODMAS के नियम से (पहले कोष्ठक, फिर बाएँ से दाएँ ÷ और ×, फिर + और −): मान = 45।", "level": "tough"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "Amit starts a business with ₹40,000. After 6 months, Arjun joins with ₹36,000. At the end of the year the profit is ₹29,000. What is Arjun's share?", "o": ["₹9,000", "₹14,500", "₹11,000", "₹20,000"], "a": 0, "e": "Capital × months = 40000×12 : 36000×6 = 20 : 9. Share = 9/29 × ₹29,000 = ₹9,000.", "qh": "अमित ₹40,000 से कारोबार शुरू करता है। 6 महीने बाद अर्जुन ₹36,000 लेकर जुड़ता है। साल के आखिर में लाभ ₹29,000 है। अर्जुन का हिस्सा कितना है?", "oh": ["₹9,000", "₹14,500", "₹11,000", "₹20,000"], "eh": "पूँजी × महीने = 40000×12 : 36000×6 = 20 : 9। हिस्सा = 9/29 × ₹29,000 = ₹9,000।", "level": "easy"}, {"s": "Mathematics", "t": "Trigonometry", "q": "If tan θ = 3/4, what is sin θ? (θ is acute)", "o": ["3/5", "4/5", "4/3", "5/4"], "a": 0, "e": "Opposite = 3, adjacent = 4, hypotenuse = √(3² + 4²) = 5. sin θ = 3/5.", "qh": "अगर tan θ = 3/4 है, तो sin θ क्या है? (θ न्यून कोण है)", "oh": ["3/5", "4/5", "4/3", "5/4"], "eh": "सामने की भुजा = 3, आसन्न भुजा = 4, कर्ण = √(3² + 4²) = 5. sin θ = 3/5।", "level": "easy"}, {"s": "Mathematics", "t": "Algebra", "q": "The cost of 3 pens and 3 notebooks is ₹69, and the cost of 4 pens and 7 notebooks is ₹143. What is the cost of one notebook?", "o": ["₹19", "₹17", "₹6", "₹23"], "a": 1, "e": "3p + 3n = 69, 4p + 7n = 143. Eliminating p: n = (3×143 − 4×69)/(3×7 − 4×3) = ₹17; pen = ₹6.", "qh": "3 पेन और 3 कॉपियों का दाम ₹69 है, और 4 पेन और 7 कॉपियों का दाम ₹143 है। एक कॉपी का दाम कितना है?", "oh": ["₹19", "₹17", "₹6", "₹23"], "eh": "3p + 3n = 69, 4p + 7n = 143। p हटाने पर: n = (3×143 − 4×69)/(3×7 − 4×3) = ₹17; पेन = ₹6।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Statement and Conclusion", "q": "Read the statement and the conclusions/assumptions given below and decide which of them logically follow(s).\nStatement: Raju is the tallest boy in his class.\nConclusions:\nI. No boy in Raju's class is taller than him.\nII. Raju is the tallest boy in his school.", "o": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "a": 0, "e": "Tallest in class means nobody in the class is taller (I). The school is a bigger group, so II cannot be said.", "qh": "नीचे दिए कथन और निष्कर्ष/धारणाएँ पढ़कर तय कीजिए कि कौन-सा/से तर्क के आधार पर सही है/हैं।\nकथन: राजू अपनी कक्षा का सबसे लंबा लड़का है।\nनिष्कर्ष:\nI. राजू की कक्षा में कोई लड़का उससे लंबा नहीं है।\nII. राजू अपने स्कूल का सबसे लंबा लड़का है।", "oh": ["केवल निष्कर्ष I सही है", "केवल निष्कर्ष II सही है", "I और II दोनों सही हैं", "न I सही है, न II"], "eh": "कक्षा में सबसे लंबा = कक्षा में कोई उससे लंबा नहीं (I)। स्कूल बड़ा समूह है, II नहीं कह सकते।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nGWCC : KVEB :: ZIUX : ?", "o": ["WWHD", "VJSY", "DHWX", "DHWW"], "a": 3, "e": "Each letter moves +4, -1, +2, -1 in order. ZIUX → DHWW.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nGWCC : KVEB :: ZIUX : ?", "oh": ["WWHD", "VJSY", "DHWX", "DHWW"], "eh": "हर अक्षर क्रम से +4, -1, +2, -1 खिसकता है। ZIUX → DHWW।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Ranking", "q": "In a row of 36 people, Naveen is 10th from the left and Manoj is 8th from the right. How many people are there between them?", "o": ["18", "16", "17", "19"], "a": 0, "e": "Manoj is 29th from the left. Between = 29 − 10 − 1 = 18.", "qh": "36 लोगों की पंक्ति में नवीन बाएँ से 10वें और मनोज दाएँ से 8वें स्थान पर है। दोनों के बीच कितने लोग हैं?", "oh": ["18", "16", "17", "19"], "eh": "मनोज बाएँ से 29वें स्थान पर है। बीच में = 29 − 10 − 1 = 18।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "Pointing to a photograph, a man said, \"This person is the wife of the only son of my mother.\" How is the person in the photograph related to the man?", "o": ["Sister", "Wife", "Sister-in-law", "Mother"], "a": 1, "e": "Simplify from the end: 'the wife of the only son of my mother' points to the man's wife.", "qh": "एक तस्वीर की ओर इशारा करते हुए एक आदमी ने कहा, \"यह व्यक्ति मेरी माँ के इकलौते बेटे की पत्नी है।\" तस्वीर वाला व्यक्ति उस आदमी का क्या लगता है?", "oh": ["बहन", "पत्नी", "भाभी/साली", "माँ"], "eh": "आखिर से सरल करें: 'मेरी माँ के इकलौते बेटे की पत्नी' = पत्नी।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\n10 : 1000 :: 9 : ?", "o": ["738", "81", "729", "747"], "a": 2, "e": "Rule: x → x³. 10 → 1000, so 9 → 729.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\n10 : 1000 :: 9 : ?", "oh": ["738", "81", "729", "747"], "eh": "नियम: x → x³। 10 → 1000, इसलिए 9 → 729।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "Which two mathematical signs should be interchanged to make the following equation correct?\n20 + 10 × 5 ÷ 18 − 18 = 10", "o": ["+ and −", "+ and ÷", "− and ÷", "− and ×"], "a": 1, "e": "Interchanging + and ÷: 20 ÷ 10 × 5 + 18 − 18 = 10. ✔", "qh": "नीचे दिए समीकरण को सही बनाने के लिए किन दो गणितीय चिह्नों को आपस में बदलना होगा?\n20 + 10 × 5 ÷ 18 − 18 = 10", "oh": ["+ और −", "+ और ÷", "− और ÷", "− और ×"], "eh": "+ और ÷ बदलने पर: 20 ÷ 10 × 5 + 18 − 18 = 10। ✔", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["89", "59", "93", "71"], "a": 2, "e": "All except 93 are prime numbers.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["89", "59", "93", "71"], "eh": "93 को छोड़कर सभी अभाज्य संख्याएँ हैं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Data Sufficiency", "q": "Question: What is the present age of Amit?\nStatement I: The sum of the ages of Amit and Deepak is 43 years.\nStatement II: Amit is 17 years younger than Deepak.\nWhich of the following is correct?", "o": ["The data in either statement I alone or statement II alone is sufficient", "The data in statement II alone is sufficient", "The data in both statements I and II together is needed", "The data in both statements together is not sufficient"], "a": 2, "e": "Neither alone is enough, but together they give one value.", "qh": "प्रश्न: अमित की अभी की आयु क्या है?\nकथन I: अमित और दीपक की आयु का योग 43 साल है।\nकथन II: अमित, दीपक से 17 साल छोटा है।\nनीचे दिए विकल्पों में से कौन-सा सही है?", "oh": ["अकेले कथन I या अकेले कथन II, कोई भी काफ़ी है", "केवल कथन II का आँकड़ा काफ़ी है", "दोनों कथन I और II साथ में चाहिए", "दोनों कथन मिलकर भी काफ़ी नहीं हैं"], "eh": "अकेले कोई काफ़ी नहीं, पर दोनों मिलकर एक ही मान देते हैं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "Study the following series of digits and answer the question.\n4 8 5 1 4 6 7 8 7 1 2 7 6 7 4 3 9 4 4 2 7 2 4 1 5\nHow many even digits are there, each of which is immediately preceded by an odd digit AND immediately followed by a digit greater than 5?", "o": ["4", "5", "6", "7"], "a": 0, "e": "Matching groups: 1 4 6, 7 8 7, 1 2 7, 7 6 7 → 4.", "qh": "नीचे दी गई अंकों की शृंखला पढ़कर प्रश्न का उत्तर दीजिए।\n4 8 5 1 4 6 7 8 7 1 2 7 6 7 4 3 9 4 4 2 7 2 4 1 5\nऐसे कितने सम अंक हैं, जिनके ठीक पहले विषम अंक हो और ठीक बाद 5 से बड़ा अंक हो?", "oh": ["4", "5", "6", "7"], "eh": "शर्त पूरी करने वाले समूह: 1 4 6, 7 8 7, 1 2 7, 7 6 7 → 4।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Venn Diagram", "q": "In a group of 60 people, 29 like tea, 29 like coffee and 5 like both. How many like only tea?", "o": ["24", "21", "31", "29"], "a": 0, "e": "Only tea = 29 − 5 = 24.", "qh": "60 लोगों के समूह में 29 को चाय पसंद है, 29 को कॉफ़ी पसंद है और 5 को दोनों पसंद हैं। कितने लोगों को केवल चाय पसंद है?", "oh": ["24", "21", "31", "29"], "eh": "केवल चाय = 29 − 5 = 24।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nB49Z, E64W, H81T, K100Q, ?", "o": ["N120N", "N123N", "N121N", "M121M"], "a": 2, "e": "First letter +3; number: consecutive squares; last letter -3. So ? = N121N.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nB49Z, E64W, H81T, K100Q, ?", "oh": ["N120N", "N123N", "N121N", "M121M"], "eh": "पहला अक्षर +3; संख्या: लगातार वर्ग संख्याएँ; आखिरी अक्षर -3। इसलिए ? = N121N।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "R is the father of Q. Q is the sister of G. G is the son of C. How is R related to C?", "o": ["Father", "Son-in-law", "Brother-in-law", "Husband"], "a": 3, "e": "Draw the family tree: R → Q: father; Q → G: sister; G → C: son. So R is the husband of C.", "qh": "R, Q का पिता है। Q, G की बहन है। G, C का बेटा है। R का C से क्या संबंध है?", "oh": ["पिता", "दामाद", "साला/देवर/जीजा", "पति"], "eh": "परिवार का चार्ट बनाएँ: R → Q: पिता; Q → G: बहन; G → C: बेटा। इसलिए R, C का पति है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'SPOON' is coded as 167 and 'BOOK' is coded as 95. How will 'GLASS' be coded in that language?", "o": ["135", "58", "130", "125"], "a": 3, "e": "Sum of letter positions: SPOON = 19+16+15+15+14 = 79, BOOK = 2+15+15+11 = 43. Rule: code = 2 × sum + 9 (2 × 79 + 9 = 167, 2 × 43 + 9 = 95). GLASS = 7+12+1+19+19 = 58, so code = 2 × 58 + 9 = 125.", "qh": "एक कोड भाषा में 'SPOON' को 167 और 'BOOK' को 95 लिखा जाता है। उसी भाषा में 'GLASS' को कैसे लिखा जाएगा?", "oh": ["135", "58", "130", "125"], "eh": "स्थितियों का योग: SPOON = 19+16+15+15+14 = 79, BOOK = 2+15+15+11 = 43। नियम: कोड = 2 × योग + 9 (2 × 79 + 9 = 167, 2 × 43 + 9 = 95)। GLASS = 7+12+1+19+19 = 58, तो कोड = 2 × 58 + 9 = 125।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "W, P, L, K, F, E and H are sitting in a row, all facing North.\nF does not sit at either end.\nL does not sit at either end.\nExactly 3 persons sit between W and P.\nExactly 2 persons sit between W and L.\nExactly 2 persons sit between H and P.\nE is not an immediate neighbour of L.\nExactly 4 persons sit between F and W.\nL sits second to the right of F.\nWho sits exactly in the middle of the row?", "o": ["P", "L", "E", "H"], "a": 1, "e": "Only one order fits all clues (left to right): E F P L K H W. Answer: L.", "qh": "W, P, L, K, F, E और H एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं।\nF किसी भी छोर पर नहीं बैठा है।\nL किसी भी छोर पर नहीं बैठा है।\nW और P के बीच ठीक 3 व्यक्ति बैठे हैं।\nW और L के बीच ठीक 2 व्यक्ति बैठे हैं।\nH और P के बीच ठीक 2 व्यक्ति बैठे हैं।\nE, L का ठीक पड़ोसी नहीं है।\nF और W के बीच ठीक 4 व्यक्ति बैठे हैं।\nL, F के दाईं ओर दूसरे स्थान पर बैठा है।\nपंक्ति के ठीक बीच में कौन बैठा है?", "oh": ["P", "L", "E", "H"], "eh": "सभी शर्तों पर केवल एक क्रम बैठता है (बाएँ से दाएँ): E F P L K H W। उत्तर: L।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n26, 50, 122, 170, 290, ?", "o": ["580", "365", "364", "362"], "a": 3, "e": "Rule: (consecutive primes)² + 1 So ? = 362.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n26, 50, 122, 170, 290, ?", "oh": ["580", "365", "364", "362"], "eh": "नियम: (लगातार अभाज्य संख्याएँ)² + 1 इसलिए ? = 362।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\nB 2 £ # 2 3 B Q I A B @ A 5 7 4 7 2 7 * M R\nHow many numbers are there in the arrangement, each of which is immediately preceded by a letter and immediately followed by a symbol?", "o": ["3", "2", "1", "4"], "a": 2, "e": "Matching places: B2£ → 1.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\nB 2 £ # 2 3 B Q I A B @ A 5 7 4 7 2 7 * M R\nइस क्रम में ऐसी कितनी संख्याएँ हैं, जिनके ठीक पहले एक अक्षर और ठीक बाद एक चिह्न है?", "oh": ["3", "2", "1", "4"], "eh": "शर्त पूरी करने वाले स्थान: B2£ → 1।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "J, R, A, C and L are sitting around a circular table, all facing the centre.\nA sits immediately to the left of J.\nR sits immediately to the right of J.\nL sits immediately to the right of C.\nWho sits to the immediate right of J?", "o": ["A", "L", "C", "R"], "a": 3, "e": "Only one arrangement fits. Going to the right (anticlockwise) from J: J → R → C → L → A. Answer: R.", "qh": "J, R, A, C और L एक गोल मेज़ के चारों ओर केंद्र की ओर मुँह करके बैठे हैं।\nA, J के ठीक बाईं ओर बैठा है।\nR, J के ठीक दाईं ओर बैठा है।\nL, C के ठीक दाईं ओर बैठा है।\nJ के ठीक दाईं ओर कौन बैठा है?", "oh": ["A", "L", "C", "R"], "eh": "केवल एक व्यवस्था बैठती है। J से दाईं ओर (घड़ी की उलटी दिशा में) चलें: J → R → C → L → A। उत्तर: R।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["LPRS", "PTVW", "BFHI", "HMOP"], "a": 3, "e": "In LPRS, PTVW, BFHI the gaps are +4, +2, +1; in HMOP they are +5, +2, +1.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["LPRS", "PTVW", "BFHI", "HMOP"], "eh": "LPRS, PTVW, BFHI में अंतर +4, +2, +1 है; HMOP में +5, +2, +1 है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nSome clocks are lamps.\nSome lamps are bricks.\nConclusions:\nI. No clocks are bricks.\nII. No bricks are lamps.", "o": ["Only conclusion I follows", "Neither I nor II follows", "Only conclusion II follows", "Both I and II follow"], "a": 1, "e": "Each conclusion fails in at least one possible diagram, and they do not form an either–or pair.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nकुछ घड़ियाँ लैंप हैं।\nकुछ लैंप ईंटें हैं।\nनिष्कर्ष:\nI. कोई भी घड़ियाँ ईंटें नहीं है।\nII. कोई भी ईंटें लैंप नहीं है।", "oh": ["केवल निष्कर्ष I सही है", "न I सही है, न II", "केवल निष्कर्ष II सही है", "I और II दोनों सही हैं"], "eh": "हर निष्कर्ष किसी न किसी आरेख में गलत हो जाता है, और ये 'या तो–या' वाली जोड़ी नहीं हैं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["Spoon", "Hammer", "Screwdriver", "Spanner"], "a": 0, "e": "Spoon is a kitchen item; the others are tools.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["चम्मच", "हथौड़ा", "पेचकस", "पाना"], "eh": "चम्मच रसोई का सामान है; बाकी औज़ार हैं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\n# % # 8 © 4 £ D 5 T G D 3 & M % 8 N 9 G @ D\nHow many numbers are there in the arrangement, each of which is immediately preceded by a letter and immediately followed by a symbol?", "o": ["1", "3", "2", "4"], "a": 0, "e": "Matching places: D3& → 1.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\n# % # 8 © 4 £ D 5 T G D 3 & M % 8 N 9 G @ D\nइस क्रम में ऐसी कितनी संख्याएँ हैं, जिनके ठीक पहले एक अक्षर और ठीक बाद एक चिह्न है?", "oh": ["1", "3", "2", "4"], "eh": "शर्त पूरी करने वाले स्थान: D3& → 1।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Deepak starts from point P, walks 12 km towards West, then turns left and walks 2 km, then turns left and walks 15 km, then turns left and walks 6 km. How far is Deepak from point P now?", "o": ["35 km", "7 km", "4 km", "5 km"], "a": 3, "e": "Net East–West = +3 km, net North–South = +4 km; distance = √(3² + 4²) = 5 km.", "qh": "दीपक बिंदु P से शुरू करके पश्चिम की ओर 12 km चलता है, फिर बाएँ मुड़कर 2 km चलता है, फिर बाएँ मुड़कर 15 km चलता है, फिर बाएँ मुड़कर 6 km चलता है। अब दीपक बिंदु P से कितनी दूर है?", "oh": ["35 km", "7 km", "4 km", "5 km"], "eh": "कुल पूर्व–पश्चिम = +3 km, कुल उत्तर–दक्षिण = +4 km; दूरी = √(3² + 4²) = 5 km।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "If '+' means '−', '−' means '×', '×' means '÷', '÷' means '+', then what is the value of the following expression?\n24 − 17 ÷ 9 = ?", "o": ["834", "417", "427", "414"], "a": 1, "e": "Replace the signs: 24 × 17 + 9 = 417 (using BODMAS).", "qh": "अगर '+' का मतलब '−', '−' का मतलब '×', '×' का मतलब '÷', '÷' का मतलब '+' हो, तो नीचे दिए व्यंजक का मान क्या होगा?\n24 − 17 ÷ 9 = ?", "oh": ["834", "417", "427", "414"], "eh": "चिह्न बदलें: 24 × 17 + 9 = 417 (BODMAS से)।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "The following questions are based on the five three-digit numbers given below.\n483   973   348   197   586\nIf the digits of each number are written in reverse order, what is the sum of the first and third digits of the second smallest number so formed?", "o": ["7", "10", "6", "5"], "a": 0, "e": "Reversed numbers in order: 379, 384, 685, 791, 843. Second smallest = 384; 3 + 4 = 7.", "qh": "नीचे दी गई पाँच तीन-अंकीय संख्याओं के आधार पर प्रश्न का उत्तर दीजिए।\n483   973   348   197   586\nअगर हर संख्या के अंकों को उलटे क्रम में लिखा जाए, तो बनी हुई दूसरी सबसे छोटी संख्या के पहले और तीसरे अंक का योग क्या होगा?", "oh": ["7", "10", "6", "5"], "eh": "उलटी संख्याएँ क्रम में: 379, 384, 685, 791, 843। दूसरी सबसे छोटी = 384; 3 + 4 = 7।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nI49Z, K64Y, M81X, O100W, ?", "o": ["R121V", "Q121W", "P121U", "Q121V"], "a": 3, "e": "First letter +2; number: consecutive squares; last letter -1. So ? = Q121V.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nI49Z, K64Y, M81X, O100W, ?", "oh": ["R121V", "Q121W", "P121U", "Q121V"], "eh": "पहला अक्षर +2; संख्या: लगातार वर्ग संख्याएँ; आखिरी अक्षर -1। इसलिए ? = Q121V।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nBE, FI, JM, NQ, ?", "o": ["RV", "RW", "QU", "RU"], "a": 3, "e": "Letter positions move by +4, +4 (for 1st, 2nd letters). So ? = RU.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nBE, FI, JM, NQ, ?", "oh": ["RV", "RW", "QU", "RU"], "eh": "अक्षरों की स्थिति +4, +4 से बदलती है (पहले, दूसरे अक्षर के लिए)। इसलिए ? = RU।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Clock (Mirror Image)", "q": "A clock shows the time 4:50. What time will its mirror image show?", "o": ["8:10", "7:10", "6:10", "7:20"], "a": 1, "e": "Mirror time = 11:60 − 4:50 = 7:10.", "qh": "एक घड़ी 4:50 का समय दिखा रही है। दर्पण में उसका प्रतिबिंब कौन-सा समय दिखाएगा?", "oh": ["8:10", "7:10", "6:10", "7:20"], "eh": "दर्पण का समय = 11:60 − 4:50 = 7:10।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nHungry : Eat :: Tired : ?", "o": ["Rest", "Run", "Sleepy", "Work"], "a": 0, "e": "Relation: 'need'. Hungry – Eat, so Tired – Rest.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nभूखा : खाना :: थका हुआ : ?", "oh": ["आराम", "दौड़ना", "नींद में", "काम"], "eh": "संबंध: 'ज़रूरत'। भूखा – खाना, इसलिए थका हुआ – आराम।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Naveen starts from point P, walks 5 km towards East, then turns right and walks 4 km, then turns right and walks 2 km, then turns right and walks 12 km. In which direction is Naveen now with respect to point P?", "o": ["North-East", "South-West", "South", "South-East"], "a": 0, "e": "Net East–West = +3 km, net North–South = +8 km; direction = North-East.", "qh": "नवीन बिंदु P से शुरू करके पूर्व की ओर 5 km चलता है, फिर दाएँ मुड़कर 4 km चलता है, फिर दाएँ मुड़कर 2 km चलता है, फिर दाएँ मुड़कर 12 km चलता है। अब नवीन बिंदु P से किस दिशा में है?", "oh": ["उत्तर-पूर्व", "दक्षिण-पश्चिम", "दक्षिण", "दक्षिण-पूर्व"], "eh": "कुल पूर्व–पश्चिम = +3 km, कुल उत्तर–दक्षिण = +8 km; दिशा = उत्तर-पूर्व।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'BUCKET' is written as 'UFLDVC'. How will 'PARROT' be written in that language?", "o": ["QBSSPU", "UPSSBP", "UPSSBQ", "UPTSBQ"], "a": 2, "e": "Rule: the word is reversed and each letter moves +1. Applying it to PARROT gives UPSSBQ.", "qh": "एक कोड भाषा में 'BUCKET' को 'UFLDVC' लिखा जाता है। उसी भाषा में 'PARROT' को कैसे लिखा जाएगा?", "oh": ["QBSSPU", "UPSSBP", "UPSSBQ", "UPTSBQ"], "eh": "नियम: शब्द उलटा करके हर अक्षर +1 खिसकता है। PARROT पर लगाने से UPSSBQ मिलता है।", "level": "medium"}]});
